import{_ as t,o,c as n,a0 as s}from"./chunks/framework.CBux2OW7.js";const u=JSON.parse('{"title":"CI/CD with GitHub Actions","description":"","frontmatter":{},"headers":[],"relativePath":"deployment/github-actions.md","filePath":"deployment/github-actions.md"}'),i={name:"deployment/github-actions.md"};function a(r,e,c,l,d,h){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ci-cd-with-github-actions" tabindex="-1">CI/CD with GitHub Actions <a class="header-anchor" href="#ci-cd-with-github-actions" aria-label="Permalink to &quot;CI/CD with GitHub Actions&quot;">​</a></h1><p>TechyNews uses GitHub Actions for continuous integration and deployment. The pipeline is designed to ensure that only tested, verified code reaches the production server.</p><h2 id="deployment-workflow" tabindex="-1">Deployment Workflow <a class="header-anchor" href="#deployment-workflow" aria-label="Permalink to &quot;Deployment Workflow&quot;">​</a></h2><p>The primary workflow is triggered on pushes to the <code>main</code> branch.</p><ol><li><strong>Checkout Code:</strong> The action checks out the latest commit.</li><li><strong>Setup Environment:</strong> Sets up PHP, Composer, Node.js, and npm.</li><li><strong>Install Dependencies:</strong> Runs <code>composer install</code> and <code>npm ci</code>.</li><li><strong>Build Assets:</strong> Executes <code>npm run build</code> to compile the Vite frontend assets (including SSR bundles if applicable).</li><li><strong>Run Tests:</strong> Runs the automated test suite (PHPUnit, Jest).</li><li><strong>Deploy via Rsync:</strong> If all tests pass, the compiled assets and codebase are securely deployed to the production cPanel server using <code>rsync</code> over SSH.</li><li><strong>Post-Deploy Hooks:</strong> Clears the Laravel cache (<code>php artisan optimize:clear</code>) on the production server.</li></ol><h2 id="secrets-management" tabindex="-1">Secrets Management <a class="header-anchor" href="#secrets-management" aria-label="Permalink to &quot;Secrets Management&quot;">​</a></h2><p>The deployment action requires several GitHub repository secrets:</p><ul><li><code>SSH_PRIVATE_KEY</code>: For secure access to the production server.</li><li><code>SERVER_USER</code>: The cPanel username.</li><li><code>SERVER_IP</code>: The production server IP address.</li><li><code>SERVER_PORT</code>: Custom SSH port (e.g., 21098).</li></ul><h2 id="rollbacks" tabindex="-1">Rollbacks <a class="header-anchor" href="#rollbacks" aria-label="Permalink to &quot;Rollbacks&quot;">​</a></h2><p>Because deployments are atomic (and rely on version control), rolling back involves reverting the problematic commit on the <code>main</code> branch and pushing, which triggers a new, stable build and deployment.</p>',10)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
